const { sbRequest } = require('/home/node/scripts/cvpro-helpers.js');
const yesterday = new Date(Date.now() - 86400000).toISOString();
const yDate = yesterday.split('T')[0];

const convCount = await sbRequest($http, 'GET', `/rest/v1/conversations?created_at=gte.${yesterday}&select=id`);
const humanTakeover = await sbRequest($http, 'GET', `/rest/v1/conversations?created_at=gte.${yesterday}&human_takeover=eq.true&select=id`);
const qualified = await sbRequest($http, 'GET', `/rest/v1/customers?lead_stage=eq.qualified&updated_at=gte.${yesterday}&select=id`);
const cvsAnalyzed = await sbRequest($http, 'GET', `/rest/v1/cv_analyses?created_at=gte.${yesterday}&select=id`);
const won = await sbRequest($http, 'GET', `/rest/v1/customers?lead_stage=eq.won&updated_at=gte.${yesterday}&select=id`);
const offers = await sbRequest($http, 'GET', `/rest/v1/customers?lead_stage=in.(offer_sent,negotiation)&updated_at=gte.${yesterday}&select=id`);

const totalConv = convCount?.length || 0;
const htCount = humanTakeover?.length || 0;
const revenueAed = (won?.length || 0) * 599;

await sbRequest($http, 'POST', '/rest/v1/daily_analytics', {
  date: yDate,
  total_conversations: totalConv,
  ai_resolved: Math.max(0, totalConv - htCount),
  human_takeover: htCount,
  leads_qualified: qualified?.length || 0,
  cvs_analyzed: cvsAnalyzed?.length || 0,
  offers_sent: offers?.length || 0,
  sales_won: won?.length || 0,
  revenue_aed: revenueAed,
  avg_response_time_seconds: 45,
}, { Prefer: 'resolution=merge-duplicates' });

return [{ json: { date: yDate, revenue: revenueAed } }];
